//! Explicit ordered pointwise color-chain .cube bake. Spatial/temporal effects cannot be LUTs.
use crate::{effects::{self,Frame,Params},model::Effect,color::lut::Lut};use serde::{Serialize,Deserialize};use std::{collections::BTreeMap,io::Write};
#[derive(Deserialize)]#[serde(tag="type",rename_all="snake_case",deny_unknown_fields)]
pub enum Step{
 Effect{kind:String,#[serde(default)]params:Params,#[serde(default)]strings:BTreeMap<String,String>},
 #[cfg(feature="native-ocio")]Ocio{config_path:String,source:String,destination:String},
 #[cfg(feature="native-ocio")]OcioView{config_path:String,source:String,display:String,view:String},
}
const ALLOWED:&[&str]=&["linear_grade","color_managed","point_curves","lab_match","cdl","color_space","primaries","log_wheels","rgb_curves","hue_curves","film_print","print_stock","bleach_bypass","white_balance","color_transfer","tonemap","highlight_rolloff","split_toning","exposure","contrast","saturation","temperature","tint","color_wheels","curves","teal_orange","levels","brightness_contrast","channel_mixer","colorize","invert","sepia","lut","hsl","luminance_shoulder","white_adaptation","gamut_ray"];
#[derive(Serialize)]pub struct ErrorMetrics{pub tested_pixels:usize,pub max_abs:f64,pub p99_abs:f64,pub rms:f64}
#[derive(Serialize)]pub struct Report{pub path:String,pub size:usize,pub entries:usize,pub domain_min:[f32;3],pub domain_max:[f32;3],pub steps:usize,pub time:f64,pub out_of_range_rows:usize,pub approximation:ErrorMetrics,pub note:&'static str}
enum Compiled{Effect(Effect),#[cfg(feature="native-ocio")]Ocio(super::ocio_config::Processor)}
pub struct Chain{steps:Vec<Compiled>,time:f64}
impl Chain{
 pub fn new(steps:Vec<Step>,time:f64)->Result<Self,String>{if !time.is_finite()||steps.is_empty()||steps.len()>64{return Err("need1..64steps and finite frozen time".into())}let mut compiled=vec![];
 for step in steps{match step{Step::Effect{kind,params,strings}=>{if !ALLOWED.contains(&kind.as_str())||strings.contains_key("mask_layer")||strings.contains_key("ocio_domain"){return Err(format!("cannot bake spatial/masked/implicitOCIO effect {kind}"))}let mut probe=Frame{w:1,h:1,d:vec![0.18,0.18,0.18,1.]};effects::apply(&kind,&params,&strings,&mut probe,time,0)?;compiled.push(Compiled::Effect(Effect{id:String::new(),kind,params,strings}));},
 #[cfg(feature="native-ocio")]Step::Ocio{config_path,source,destination}=>compiled.push(Compiled::Ocio(super::ocio_config::Config::from_file(config_path)?.processor(&source,&destination)?)),
 #[cfg(feature="native-ocio")]Step::OcioView{config_path,source,display,view}=>compiled.push(Compiled::Ocio(super::ocio_config::Config::from_file(config_path)?.display_processor(&source,&display,&view)?)),
 }}Ok(Self{steps:compiled,time})}
 pub fn apply(&self,f:&mut Frame)->Result<(),String>{super::frame::validate(f)?;for step in &self.steps{crate::guard::check();match step{Compiled::Effect(e)=>effects::apply(&e.kind,&e.params,&e.strings,f,self.time,0)?,#[cfg(feature="native-ocio")]Compiled::Ocio(p)=>p.apply(f)?,}}super::frame::validate(f)}
 pub fn bake(&self,n:usize,min:[f32;3],max:[f32;3])->Result<Lut,String>{if ![17,33,65].contains(&n)||(0..3).any(|j|!min[j].is_finite()||!max[j].is_finite()||min[j].abs()>16.||max[j].abs()>16.||max[j]-min[j]<1e-6){return Err("size17/33/65, increasingfinite domain perchannel within+-16 required".into())}
 let mut f=Frame::new(n*n,n);for b in 0..n{crate::guard::check();for g in 0..n{for r in 0..n{let i=((b*n+g)*n+r)*4;for(j,k)in [r,g,b].iter().enumerate(){f.d[i+j]=min[j]+(max[j]-min[j])* *k as f32/(n-1) as f32}f.d[i+3]=1.;}}}self.apply(&mut f)?;let mut data=Vec::with_capacity(n*n*n);for p in f.d.chunks_exact(4){if p[..3].iter().any(|v|v.abs()>1e6){return Err("LUT output exceeds supportedportablevaluebound1e6".into())}data.push([p[0],p[1],p[2]]);}Ok(Lut{n,data,min,max})}
 pub fn error_metrics(&self,l:&Lut)->Result<ErrorMetrics,String>{let mut inputs=vec![];let mut seed=7u64;for _ in 0..4096{let mut p=[0.;3];for j in 0..3{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);p[j]=l.min[j]+(l.max[j]-l.min[j])*(seed>>40) as f32/16777215.;}inputs.push(p);}for x in [0.,0.00001,0.001,0.003,0.0078125,0.01,0.18,0.5,1.]{inputs.push(std::array::from_fn(|j|l.min[j]+x*(l.max[j]-l.min[j])));}let mut f=Frame{w:inputs.len(),h:1,d:inputs.iter().flat_map(|v|[v[0],v[1],v[2],1.]).collect()};self.apply(&mut f)?;let mut errors=vec![];for(i,p)in inputs.iter().enumerate(){let v=l.sample(*p);for j in 0..3{errors.push((v[j]-f.d[i*4+j]).abs() as f64);}}errors.sort_by(|a,b|a.total_cmp(b));Ok(ErrorMetrics{tested_pixels:inputs.len(),max_abs:*errors.last().unwrap(),p99_abs:errors[errors.len()*99/100],rms:(errors.iter().map(|v|v*v).sum::<f64>()/errors.len() as f64).sqrt()})}
 pub fn write(&self,l:&Lut,path:&str)->Result<Report,String>{if !path.to_lowercase().ends_with(".cube"){return Err("output requires .cube".into())}let mut text=String::new();use std::fmt::Write as FmtWrite;write!(text,"TITLE \"Kimo explicit pointwise chain\"\nLUT_3D_SIZE {}\nDOMAIN_MIN {} {} {}\nDOMAIN_MAX {} {} {}\n",l.n,l.min[0],l.min[1],l.min[2],l.max[0],l.max[1],l.max[2]).map_err(|e|e.to_string())?;for(i,row)in l.data.iter().enumerate(){if i%4096==0{crate::guard::check()}writeln!(text,"{:.9} {:.9} {:.9}",row[0],row[1],row[2]).map_err(|e|e.to_string())?;}if text.len()>32*1024*1024{return Err("LUTfilebudget exceeded".into())}let serialized=Lut::parse(&text)?;let approximation=self.error_metrics(&serialized)?;
 let mut file=std::fs::File::create(path).map_err(|e|e.to_string())?;file.write_all(text.as_bytes()).map_err(|e|e.to_string())?;
 Ok(Report{path:path.into(),size:l.n,entries:l.data.len(),domain_min:l.min,domain_max:l.max,steps:self.steps.len(),time:self.time,out_of_range_rows:l.data.iter().filter(|p|p.iter().any(|v|*v<0.||*v>1.)).count(),approximation,note:"Static RGB pointwise approximation. Tetrahedral interpolation tested; targetsoftware may interpolate differently. Input outside domain clamps; output not clipped. No alpha/spatial/temporal transform or automatic encoding/default inference."})}
}
